def delta(s):
    return (s.count("{"), s.count("}"), s.count("("), s.count(")"),
            s.count("["), s.count("]"))


def _imbalances_ok(before, after):
    """True when no bracket pair's imbalance changed (balanced code may
    legitimately raise the counts, so exact equality is wrong)."""
    b, a = delta(before), delta(after)
    return ((a[0] - a[1]) == (b[0] - b[1]) and (a[2] - a[3]) == (b[2] - b[3])
            and (a[4] - a[5]) == (b[4] - b[5]))


def _strip_strings(text):
    """Remove single/double-quoted string contents so paren counting
    never trips over a paren inside a string literal."""
    return re.sub(r"'[^']*'|\"[^\"]*\"", "''", text)


_CALL_NAME_RE = re.compile(r"^\s*(?:withTimeout\()?([A-Za-z_$][\w$]*)\(")
_MAPPING_RE = re.compile(
    r"^([ \t]*)(\w+): results\[(\d+)\]\.status === 'fulfilled' \? "
    r"results\[\d+\]\.value : \[\],?[ \t]*$", re.M)


def _parse_batch_entries(body):
    """Split a Promise.allSettled array body into call entries.

    Paren-depth aware: a call that spans several lines counts once.
    Returns a list of {name, text, start, end} with start/end as
    character offsets within body.
    """
    lines = body.split("\n")
    entries = []
    depth = 0
    cur_lines = None
    cur_start = 0
    offset = 0
    for ln in lines:
        stripped = ln.strip()
        if cur_lines is None:
            if not stripped or "(" not in _strip_strings(ln):
                offset += len(ln) + 1
                continue
            cur_lines = []
            cur_start = offset
        cur_lines.append(ln)
        code = _strip_strings(ln)
        depth += code.count("(") - code.count(")")
        if depth <= 0 and stripped.endswith(","):
            text = "\n".join(cur_lines)
            m = _CALL_NAME_RE.match(text)
            entries.append({
                "name": m.group(1) if m else "?",
                "text": text,
                "start": cur_start,
                "end": offset + len(ln),
            })
            cur_lines = None
            depth = 0
        offset += len(ln) + 1
    return entries


def _parse_mappings(src):
    """Return (mapping dict index->field, last mapping match)."""
    mapping = {}
    last = None
    for m in _MAPPING_RE.finditer(src):
        mapping[int(m.group(3))] = m.group(2)
        last = m
    return mapping, last


def _object_span(src, decl_re):
    """Find the { ... } object declared by decl_re. Returns
    (open_brace_index, close_brace_index) or None. Brace-count scan
    that skips single-quoted string spans (hex colors and icon
    escapes can contain braces)."""
    m = re.search(decl_re, src)
    if not m:
        return None
    start = src.find("{", m.start())
    if start == -1:
        return None
    depth = 0
    i = start
    in_str = False
    esc = False
    while i < len(src):
        ch = src[i]
        if in_str:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == "'":
                in_str = False
        else:
            if ch == "'":
                in_str = True
            elif ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    return (start, i)
        i += 1
    return None


def _add_object_entry(src, decl_re, entry, label):
    """Add `entry` to the object declared by decl_re. Returns
    (new_src, status) where status is 'added', 'already', or an error
    string. NEVER uses a negated-brace regex on these objects."""
    span = _object_span(src, decl_re)
    if span is None:
        return src, "object-not-found"
    open_i, close_i = span
    obj = src[open_i:close_i + 1]
    key = entry.split(":")[0].strip()
    if (key + ":") in obj or (key + " :") in obj:
        return src, "already"
    if "\n" not in obj:
        return src[:close_i] + ", " + entry + src[close_i:], "added"
    nl = src.rfind("\n", 0, close_i)
    indent = src[nl + 1:close_i]
    if indent.strip() != "":
        return src[:close_i] + ", " + entry + src[close_i:], "added"
    k = nl - 1
    while k >= 0 and src[k] in " \t\r\n":
        k -= 1
    if k >= 0 and src[k] != ",":
        src = src[:k + 1] + "," + src[k + 1:]
        close_i += 1
        nl = src.rfind("\n", 0, close_i)
        indent = src[nl + 1:close_i]
    return src[:nl + 1] + indent + entry + ",\n" + src[nl + 1:], "added"


def _add_dep_to_array(src, anchor_re, dep, label):
    """Add dep to the deps array that closes the hook found by
    anchor_re (a useCallback/useMemo start). Returns (new_src, status)
    where status is 'added', 'already', or an error string."""
    m = re.search(anchor_re, src)
    if not m:
        return src, "anchor-not-found"
    # The deps array is the first "[ ... ]);" after the hook start whose
    # opener is preceded by "}, " (useCallback) or "], " (useMemo).
    dm = None
    for cand in re.finditer(r"\n[ \t]*(?:\}|\]), \[([^\]]*)\]\);", src[m.start():], re.S):
        if re.fullmatch(r"[\w$, \n\t]*", cand.group(1)):
            dm = cand
            break
    if not dm:
        return src, "deps-array-not-found"
    content = dm.group(1)
    entries = [e.strip() for e in content.split(",") if e.strip()]
    if dep in entries:
        return src, "already"
    anchor_entry = None
    for cand_name in ("nearbyPharmacies", "nearbyFiends",
                      "nearbyActivityCenters", "nearbyShootouts"):
        if cand_name in entries:
            anchor_entry = cand_name
            break
    if "\n" not in content:
        if anchor_entry is not None:
            idx = entries.index(anchor_entry)
            entries.insert(idx + 1, dep)
        else:
            entries.append(dep)
        new_content = ", ".join(entries)
    else:
        lines = content.split("\n")
        if anchor_entry is not None:
            li = next(i for i, ln in enumerate(lines) if anchor_entry in ln)
            indent = lines[li][: len(lines[li]) - len(lines[li].lstrip())]
            lines.insert(li + 1, indent + dep + ",")
        else:
            li = max(i for i, ln in enumerate(lines) if ln.strip())
            if not lines[li].rstrip().endswith(","):
                lines[li] = lines[li].rstrip() + ","
            indent = lines[li][: len(lines[li]) - len(lines[li].lstrip())]
            lines.insert(li + 1, indent + dep + ",")
        new_content = "\n".join(lines)
    base = m.start()
    return (src[: base + dm.start(1)] + new_content
            + src[base + dm.end(1):]), "added"


def _insert_after_spread(src, type_name):
    """Insert PARK_SPREAD right after the marker spread whose type
    is type_name. Returns (new_src, ok). The spread's closing line is
    either `    })),` (simple map spread) or `    }),` (block-body
    map spread) — match the whole closing line, never a prefix of it
    (inserting inside `})),` would corrupt the spread)."""
    sm = re.search(r"      type: '" + re.escape(type_name) + r"' as const,\n", src)
    if not sm:
        return src, False
    cm = re.search(r"\n[ \t]*\}\)\),|\n[ \t]*\}\),", src[sm.end():])
    if not cm:
        return src, False
    ins = sm.end() + cm.end()
    return src[:ins] + "\n" + PARK_SPREAD.rstrip("\n") + src[ins:], True


def main():
    landed = []
    warned = []

    # ================= Part 1: services/api.ts =================
    if not API.exists():
        print("WARNING: services/api.ts not found - Park api functions NOT added")
        warned.append("api")
    else:
        asrc = API.read_text(errors="ignore")
        aorig = asrc
        missing = [n for n in PARK_API_PIECES if asrc.count("export const " + n) == 0]
        if not missing:
            print("PARK_FRONTEND_API_ALREADY_APPLIED")
            landed.append("api")
        else:
            add = "".join(PARK_API_PIECES[n] for n in missing)
            if "export default api;" in asrc:
                asrc = asrc.replace("export default api;", add + "\nexport default api;", 1)
            else:
                asrc = asrc.rstrip("\n") + "\n" + add
            print("PARK_FRONTEND_API_OK (added: " + ", ".join(missing) + ")")
            landed.append("api")
        if asrc != aorig:
            API.write_text(asrc)

    # ================= Part 2: hooks/useMapQueries.ts =================
    if not QUERIES.exists():
        print("WARNING: hooks/useMapQueries.ts not found - Park entity wiring NOT added")
        warned.append("queries")
    else:
        qsrc = QUERIES.read_text(errors="ignore")
        qorig = qsrc
        # 2a. Import — checked INSIDE the import statement only.
        m = re.search(r"\} from '\.\./services/api';", qsrc)
        if not m:
            print("WARNING: api import anchor not found in useMapQueries.ts - getParksNearby import NOT added")
            warned.append("queries-import")
        else:
            imp_start = qsrc.rfind("import {", 0, m.start())
            block = qsrc[imp_start:m.start()] if imp_start != -1 else qsrc[:m.start()]
            if "  getParksNearby,\n" in block:
                print("PARK_FRONTEND_QUERIES_IMPORT_ALREADY_APPLIED")
            elif "  getPharmaciesNearby,\n" in block:
                qsrc = qsrc.replace("  getPharmaciesNearby,\n", "  getPharmaciesNearby,\n  getParksNearby,\n", 1)
                print("PARK_FRONTEND_QUERIES_IMPORT_OK")
            elif "  getFiendsNearby,\n" in block:
                qsrc = qsrc.replace("  getFiendsNearby,\n", "  getFiendsNearby,\n  getParksNearby,\n", 1)
                print("PARK_FRONTEND_QUERIES_IMPORT_OK")
            elif "  getActivityCentersNearby,\n" in block:
                qsrc = qsrc.replace("  getActivityCentersNearby,\n", "  getActivityCentersNearby,\n  getParksNearby,\n", 1)
                print("PARK_FRONTEND_QUERIES_IMPORT_OK")
            elif "  spawnShootouts,\n" in block:
                qsrc = qsrc.replace("  spawnShootouts,\n", "  spawnShootouts,\n  getParksNearby,\n", 1)
                print("PARK_FRONTEND_QUERIES_IMPORT_OK")
            else:
                qsrc = qsrc[:m.start()] + "  getParksNearby,\n" + qsrc[m.start():]
                print("PARK_FRONTEND_QUERIES_IMPORT_OK")
        # 2b. MapEntitiesData field.
        if "parks: any[];" in qsrc:
            print("PARK_FRONTEND_QUERIES_FIELD_ALREADY_APPLIED")
        elif "  pharmacies: any[];\n" in qsrc:
            qsrc = qsrc.replace("  pharmacies: any[];\n", "  pharmacies: any[];\n  parks: any[];\n", 1)
            print("PARK_FRONTEND_QUERIES_FIELD_OK")
        elif "  fiends: any[];\n" in qsrc:
            qsrc = qsrc.replace("  fiends: any[];\n", "  fiends: any[];\n  parks: any[];\n", 1)
            print("PARK_FRONTEND_QUERIES_FIELD_OK")
        elif "  activityCenters: any[];\n" in qsrc:
            qsrc = qsrc.replace("  activityCenters: any[];\n", "  activityCenters: any[];\n  parks: any[];\n", 1)
            print("PARK_FRONTEND_QUERIES_FIELD_OK")
        elif "  shootouts: any[];\n" in qsrc:
            qsrc = qsrc.replace("  shootouts: any[];\n", "  shootouts: any[];\n  parks: any[];\n", 1)
            print("PARK_FRONTEND_QUERIES_FIELD_OK")
        else:
            print("WARNING: MapEntitiesData anchor not found - parks field NOT added")
            warned.append("queries-field")
        # 2c. Batch discovery + append the call LAST + its return mapping.
        m = re.search(r"Promise\.allSettled\(\[", qsrc)
        if not m:
            print("WARNING: Promise.allSettled anchor not found - Park call NOT added")
            warned.append("queries-batch")
        else:
            start = m.end()
            close = re.search(r"\n[ \t]*\]\);", qsrc[start:])
            if not close:
                print("WARNING: Promise.allSettled close anchor not found - Park call NOT added")
                warned.append("queries-batch")
            else:
                body = qsrc[start:start + close.start()]
                entries = _parse_batch_entries(body)
                mapping, last_map = _parse_mappings(qsrc)
                loose = sorted(set(int(x) for x in re.findall(r"results\[(\d+)\]", qsrc)))
                names = [e["name"] for e in entries]
                unmapped = [(i, entries[i]["name"]) for i in range(len(entries)) if i not in mapping]
                print(f"PARK_BATCH_DISCOVERY: calls={len(entries)} mappings={len(mapping)} loose_results_refs={loose} unmapped={unmapped}")
                print(f"PARK_BATCH_CALLS: {', '.join(names)}")
                call_idx = next((i for i, e in enumerate(entries) if e["name"] == "getParksNearby"), None)
                has_mapping = "parks" in mapping.values()
                if call_idx is not None and has_mapping:
                    print("PARK_FRONTEND_QUERIES_CALL_ALREADY_APPLIED")
                elif call_idx is not None and not has_mapping:
                    if last_map is None:
                        print("WARNING: return mapping anchor not found - parks return NOT added")
                        warned.append("queries-return")
                    else:
                        mind = last_map.group(1)
                        ins2 = last_map.end()
                        qsrc = (qsrc[:ins2] + f"\n{mind}parks: results[{call_idx}].status === 'fulfilled' "
                                f"? results[{call_idx}].value : []," + qsrc[ins2:])
                        print(f"PARK_FRONTEND_QUERIES_CALL_OK (parks mapping added at results[{call_idx}]; call was already present)")
                elif call_idx is None and has_mapping:
                    print("WARNING: parks return mapping exists but the call is missing - inconsistent state, NOT changed (hand-fix needed)")
                    warned.append("queries-inconsistent")
                else:
                    if last_map is None:
                        print("WARNING: return mapping anchor not found - Park call NOT added")
                        warned.append("queries-return")
                    elif not entries:
                        print("WARNING: entity batch could not be parsed (no calls found) - Park call NOT added")
                        warned.append("queries-batch")
                    else:
                        n = len(entries)
                        last_text = entries[-1]["text"] if entries else ""
                        lm = re.match(r"^([ \t]*)", last_text)
                        indent = lm.group(1) if lm and lm.group(1) else "        "
                        if "const withTimeout" in qsrc:
                            call_text = "withTimeout(getParksNearby(latitude, longitude)),"
                        else:
                            call_text = "getParksNearby(latitude, longitude),"
                        ins_pos = start + close.start()
                        qsrc = qsrc[:ins_pos] + "\n" + indent + call_text + qsrc[ins_pos:]
                        _, last_map2 = _parse_mappings(qsrc)
                        mind = last_map2.group(1)
                        ins2 = last_map2.end()
                        qsrc = (qsrc[:ins2] + f"\n{mind}parks: results[{n}].status === 'fulfilled' "
                                f"? results[{n}].value : []," + qsrc[ins2:])
                        print(f"PARK_FRONTEND_QUERIES_CALL_OK (parks at results[{n}]; unmapped call was {unmapped if unmapped else 'none'})")
        if not _imbalances_ok(qorig, qsrc):
            print("WARNING: unbalanced brackets - useMapQueries.ts NOT written")
            qsrc = qorig
            warned.append("queries-balance")
        if qsrc != qorig:
            QUERIES.write_text(qsrc)
            landed.append("queries")

    # ================= Part 3: app/(tabs)/index.tsx =================
    if not INDEX.exists():
        print("WARNING: app/(tabs)/index.tsx not found - Park map wiring NOT added")
        warned.append("index")
    else:
        src = INDEX.read_text(errors="ignore")
        iorig = src
        # 3a. ImageBackground import.
        if "ImageBackground" in src:
            print("PARK_FRONTEND_INDEX_BGIMPORT_ALREADY_APPLIED")
        elif "  Image,\n} from 'react-native';" in src:
            src = src.replace("  Image,\n} from 'react-native';",
                              "  Image,\n  ImageBackground,\n} from 'react-native';", 1)
            print("PARK_FRONTEND_INDEX_BGIMPORT_OK")
        else:
            mimg = re.search(r"(  Image,\n)(\} from 'react-native';)", src)
            if mimg:
                src = src[:mimg.end(1)] + "  ImageBackground,\n" + src[mimg.end(1):]
                print("PARK_FRONTEND_INDEX_BGIMPORT_OK")
            else:
                print("WARNING: react-native import anchor not found - ImageBackground NOT imported (park background will fail)")
                warned.append("index-bgimport")
        # 3b. Api imports — checked INSIDE the services/api import
        # statement only, never file-wide (the file-wide check is the
        # ALREADY_APPLIED trap: these names appear in the state block
        # below once it lands).
        m = re.search(r"\} from '\.\./\.\./services/api';", src)
        if not m:
            print("WARNING: services/api import not found in index.tsx - Park imports NOT added")
            warned.append("index-import")
        else:
            imp_start = src.rfind("import {", 0, m.start())
            block = src[imp_start:m.start()] if imp_start != -1 else src[:m.start()]
            add = ""
            for n in ("getParksNearby", "parkEnterPresence", "parkLeavePresence",
                      "parkHeartbeatPresence", "getParkPresence", "getFriendsList"):
                if n not in block:
                    add += "  " + n + ",\n"
            if not add:
                print("PARK_FRONTEND_INDEX_IMPORT_ALREADY_APPLIED")
            else:
                src = src[:m.start()] + add + src[m.start():]
                print("PARK_FRONTEND_INDEX_IMPORT_OK (added: " + add.replace("\n", " ").strip() + ")")
        # 3c. Background data-URI const.
        if "PARK_BG" in src:
            print("PARK_FRONTEND_INDEX_BG_ALREADY_APPLIED")
        elif "export default function MapScreen() {" in src:
            src = src.replace("export default function MapScreen() {",
                              "const PARK_BG = \"" + PARK_BG + "\";\n\nexport default function MapScreen() {", 1)
            print("PARK_FRONTEND_INDEX_BG_OK")
        else:
            print("WARNING: MapScreen anchor not found - park background NOT added")
            warned.append("index-bg")
        # 3d. selectedMarker type union + 3e. state / presence lifecycle.
        if "activePark" in src and "parkEnterPresence(activePark.id" in src:
            print("PARK_FRONTEND_INDEX_STATE_ALREADY_APPLIED")
        else:
            sm = re.search(r"const \[selectedMarker, setSelectedMarker\] = useState<\{.*?\} \| null>\(null\);", src, re.S)
            if not sm:
                print("WARNING: selectedMarker state not found - 'park' type / state / effect NOT added")
                warned.append("index-state")
            else:
                block = sm.group(0)
                if "'park'" in block:
                    print("PARK_FRONTEND_INDEX_UNION_ALREADY_APPLIED")
                else:
                    new_block = re.sub(r"(type: 'monster'[^;]*);", r"\1 | 'park';", block, count=1)
                    if new_block == block:
                        print("WARNING: selectedMarker type line not found - 'park' type NOT added")
                        warned.append("index-union")
                    else:
                        src = src[:sm.start()] + new_block + src[sm.end():]
                        print("PARK_FRONTEND_INDEX_UNION_OK")
                if "activePark" in src and "parkEnterPresence(activePark.id" in src:
                    print("PARK_FRONTEND_INDEX_STATE_ALREADY_APPLIED")
                else:
                    sm2 = re.search(r"const \[selectedMarker, setSelectedMarker\] = useState<\{.*?\} \| null>\(null\);", src, re.S)
                    if not sm2:
                        print("WARNING: selectedMarker state not found on re-scan - Park state NOT added")
                        warned.append("index-state")
                    else:
                        src = src[:sm2.end()] + "\n" + PARK_STATE_EFFECT.rstrip("\n") + src[sm2.end():]
                        print("PARK_FRONTEND_INDEX_STATE_OK")
        # 3f. Nearby memo.
        if "nearbyParks" in src:
            print("PARK_FRONTEND_INDEX_MEMO_ALREADY_APPLIED")
        else:
            memo_done = False
            for anchor_name in ("nearbyPharmacies", "nearbyFiends",
                                "nearbyActivityCenters", "nearbyShootouts"):
                field = {"nearbyPharmacies": "pharmacies", "nearbyFiends": "fiends",
                         "nearbyActivityCenters": "activityCenters",
                         "nearbyShootouts": "shootouts"}[anchor_name]
                anchor = f"  const {anchor_name} = useMemo(() => entitiesData?.{field} || [], [entitiesData?.{field}]);"
                if anchor in src:
                    src = src.replace(anchor, anchor + "\n  const nearbyParks = useMemo(() => entitiesData?.parks || [], [entitiesData?.parks]);", 1)
                    print("PARK_FRONTEND_INDEX_MEMO_OK")
                    memo_done = True
                    break
            if not memo_done:
                print("WARNING: nearby memo anchor not found - nearbyParks NOT added")
                warned.append("index-memo")
        # 3g. mapMarkers spread + deps.
        if "type: 'park' as const," in src:
            print("PARK_FRONTEND_INDEX_MARKERS_ALREADY_APPLIED")
        else:
            done = False
            for t in ("pharmacy", "fiend", "activityCenter", "shootout"):
                src2, ok = _insert_after_spread(src, t)
                if ok:
                    src = src2
                    print(f"PARK_FRONTEND_INDEX_MARKERS_OK (after '{t}' spread)")
                    done = True
                    break
            if not done:
                print("WARNING: marker spread anchor not found - Park markers NOT added to the map")
                warned.append("index-markers")
        src, status = _add_dep_to_array(src, r"const mapMarkers = useMemo\(", "nearbyParks", "markers")
        if status == "added":
            print("PARK_FRONTEND_INDEX_MARKERS_DEPS_OK")
        elif status == "already":
            print("PARK_FRONTEND_INDEX_MARKERS_DEPS_ALREADY_APPLIED")
        else:
            print(f"WARNING: mapMarkers deps {status} - Park markers may go stale")
            warned.append("index-markers-deps")
        # 3h. handleMarkerPress branch + deps.
        if "marker.type === 'park'" in src:
            print("PARK_FRONTEND_INDEX_PRESS_ALREADY_APPLIED")
        else:
            done = False
            press_anchors = [
                "      if (shootout) setSelectedShootout(shootout);\n    }",
                "      if (fiend) setSelectedMarker({ type: 'fiend', data: fiend });\n    }",
                "      if (pharmacy) setSelectedMarker({ type: 'pharmacy', data: pharmacy });\n    }",
                "      if (center) setSelectedMarker({ type: 'activityCenter', data: center });\n    }",
            ]
            for anchor in press_anchors:
                if anchor in src:
                    src = src.replace(anchor, anchor[:-len("\n    }")] + "\n    } else if (marker.type === 'park') {\n      const park = nearbyParks.find((p: any) => p.id === marker.id);\n      if (park) setSelectedMarker({ type: 'park', data: park });\n    }", 1)
                    print("PARK_FRONTEND_INDEX_PRESS_OK")
                    done = True
                    break
            if not done:
                print("WARNING: handleMarkerPress anchor not found - Park taps NOT wired")
                warned.append("index-press")
        src, status = _add_dep_to_array(src, r"const handleMarkerPress = useCallback\(", "nearbyParks", "press")
        if status == "added":
            print("PARK_FRONTEND_INDEX_PRESS_DEPS_OK")
        elif status == "already":
            print("PARK_FRONTEND_INDEX_PRESS_DEPS_ALREADY_APPLIED")
        else:
            print(f"WARNING: handleMarkerPress deps {status} - Park taps may use a stale list")
            warned.append("index-press-deps")
        # 3i. Popup (ENTER only) — before the mission popup, else
        # pharmacy / activityCenter / nightclub.
        if "Park • Everyone welcome" in src:
            print("PARK_FRONTEND_INDEX_POPUP_ALREADY_APPLIED")
        else:
            popup_done = False
            for ptype in ("mission", "pharmacy", "activityCenter", "nightclub"):
                anchor = f"          {{selectedMarker.type === '{ptype}' && ("
                if anchor in src:
                    src = src.replace(anchor, PARK_POPUP.rstrip("\n") + "\n" + anchor, 1)
                    print("PARK_FRONTEND_INDEX_POPUP_OK")
                    popup_done = True
                    break
            if not popup_done:
                print("WARNING: popup anchor not found - Park popup NOT added")
                warned.append("index-popup")
        # 3j. Interior modal (park picture + who is inside + cash).
        if "PARK interior" in src:
            print("PARK_FRONTEND_INDEX_INTERIOR_ALREADY_APPLIED")
        elif "      {/* Popup */}" in src:
            src = src.replace("      {/* Popup */}", PARK_MODAL.rstrip("\n") + "\n      {/* Popup */}", 1)
            print("PARK_FRONTEND_INDEX_INTERIOR_OK")
        else:
            print("WARNING: popup section anchor not found - Park interior NOT added")
            warned.append("index-interior")
        if not _imbalances_ok(iorig, src):
            print("WARNING: unbalanced brackets - index.tsx NOT written")
            src = iorig
            warned.append("index-balance")
        if src != iorig:
            INDEX.write_text(src)
            landed.append("index")

    # ================= Part 4: components/GameMap.tsx =================
    if not GAMEMAP.exists():
        print("WARNING: components/GameMap.tsx not found - Park marker NOT added")
        warned.append("gamemap")
    else:
        gsrc = GAMEMAP.read_text(errors="ignore")
        gorig = gsrc
        # 4a. Marker type union.
        uline = [ln for ln in gsrc.split("\n") if "type: 'monster'" in ln]
        if uline and "'park'" in uline[0]:
            print("PARK_FRONTEND_GAMEMAP_UNION_ALREADY_APPLIED")
        else:
            m = re.search(r"(  type: 'monster'[^;]*);", gsrc)
            if m:
                gsrc = gsrc[:m.end() - 1] + " | 'park'" + gsrc[m.end() - 1:]
                print("PARK_FRONTEND_GAMEMAP_UNION_OK")
            else:
                print("WARNING: MapMarker union not found - 'park' type NOT added")
                warned.append("gamemap-union")
        # 4b. markerColors via brace-scan (never a negated-brace regex).
        gsrc, status = _add_object_entry(gsrc, r"var markerColors\s*=\s*\{", "park: '#E91E63'", "color")
        if status == "added":
            print("PARK_FRONTEND_GAMEMAP_COLOR_OK")
        elif status == "already":
            print("PARK_FRONTEND_GAMEMAP_COLOR_ALREADY_APPLIED")
        else:
            print("WARNING: markerColors object not found - Park color NOT added")
            warned.append("gamemap-color")
        # 4c. markerIcons via brace-scan, literal basketball-player character.
        gsrc, status = _add_object_entry(gsrc, r"var markerIcons\s*=\s*\{", "park: '⛹️'", "icon")
        if status == "added":
            print("PARK_FRONTEND_GAMEMAP_ICON_OK")
        elif status == "already":
            print("PARK_FRONTEND_GAMEMAP_ICON_ALREADY_APPLIED")
        else:
            print("WARNING: markerIcons object not found - Park icon NOT added")
            warned.append("gamemap-icon")
        # 4d. Park marker branch (before the bank branch, else
        # nightclub / restaurant / casino, else the generic builder).
        if "m.type === 'park'" in gsrc:
            print("PARK_FRONTEND_GAMEMAP_BRANCH_ALREADY_APPLIED")
        else:
            done = False
            for btype in ("bank", "nightclub", "restaurant", "casino", "castle",
                          "carChase", "runaway", "packageGrab", "shootout"):
                bm = re.search(r"^([ \t]*)\} else if \(m\.type === '" + btype + r"'\) \{$",
                               gsrc, re.M)
                if bm:
                    ind = bm.group(1)
                    branch = (
                        f"{ind}}} else if (m.type === 'park') {{\n"
                        f"{ind}  var parkName = m.name || 'Park';\n"
                        f"{ind}  markerHTML = '<div style=\"width:48px;height:62px;position:relative;display:flex;flex-direction:column;align-items:center;\">' +\n"
                        f"{ind}    '<div style=\"width:42px;height:42px;border-radius:10px;background:linear-gradient(135deg,#E91E63,#AD1457);display:flex;align-items:center;justify-content:center;border:3px solid #fff;box-shadow:0 3px 10px rgba(233,30,99,0.6);font-size:22px;cursor:pointer;\">⛹️</div>' +\n"
                        f"{ind}    '<div style=\"position:absolute;bottom:0;left:50%;transform:translateX(-50%);background:rgba(173,20,87,0.9);color:#fff;padding:1px 6px;border-radius:4px;font-size:7px;font-weight:bold;white-space:nowrap;z-index:10;border:1px solid #fff;\">' + parkName + '</div>' +\n"
                        f"{ind}    '</div>';\n"
                    )
                    gsrc = gsrc[:bm.start()] + branch + gsrc[bm.start():]
                    print(f"PARK_FRONTEND_GAMEMAP_BRANCH_OK (before '{btype}' branch)")
                    done = True
                    break
            if not done:
                print("WARNING: no marker branch anchor found - Park marker branch NOT added")
                warned.append("gamemap-branch")
        # 4e. 48x62 location sizing.
        sm = re.search(r"var isLocationMarker = \(([^;]*)\);", gsrc)
        if sm and "'park'" in sm.group(1):
            print("PARK_FRONTEND_GAMEMAP_SIZING_ALREADY_APPLIED")
        elif sm:
            gsrc = gsrc[:sm.end() - 2] + " || m.type === 'park'" + gsrc[sm.end() - 2:]
            print("PARK_FRONTEND_GAMEMAP_SIZING_OK")
        else:
            print("WARNING: isLocationMarker line not found - Park sizing NOT added")
            warned.append("gamemap-sizing")
        if not _imbalances_ok(gorig, gsrc):
            print("WARNING: unbalanced brackets - GameMap.tsx NOT written")
            gsrc = gorig
            warned.append("gamemap-balance")
        if gsrc != gorig:
            GAMEMAP.write_text(gsrc)
            landed.append("gamemap")

    if warned:
        print("PARK_FRONTEND_PARTIAL: " + ",".join(landed) + " (warnings: " + ",".join(warned) + ")")
    else:
        print(MARKER)


if __name__ == "__main__":
    main()
